    def exchange_audience(
        self,
        request: ExchangeAudienceRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> ExchangeAudienceResponse:
        """
        ExchangeAudience derives a short-lived access token for a different
        audience from a still-valid refresh token, WITHOUT rotating the
        refresh chain. Use it from a multi-plane SPA that needs simultaneous
        tokens for paladin-data, paladin-admin, paladin-iam off a single login session.
        The presented refresh token must still be in the store and unexpired;
        server-side audience escalation rules apply (admin requires an
        admin-tier role on the principal).
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ExchangeAudience",
                service_name="paladin.iam.v1.AuthService",
                input=ExchangeAudienceRequest,
                output=ExchangeAudienceResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def list_my_memberships(
        self,
        request: ListMyMembershipsRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> ListMyMembershipsResponse:
        """
        ListMyMemberships returns every tenant the caller's subject belongs to.
        Under the 1:1-per-tenant user model a "membership" is a users row, so a
        subject registered in tenants A and B has two memberships with independent
        roles. Used by the SPA to render the tenant switcher.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ListMyMemberships",
                service_name="paladin.iam.v1.AuthService",
                input=ListMyMembershipsRequest,
                output=ListMyMembershipsResponse,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )
    def switch_tenant(
        self,
        request: SwitchTenantRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> SwitchTenantResponse:
        """
        SwitchTenant mints a fresh access+refresh pair scoped to a DIFFERENT
        tenant the caller is already a member of — no password re-check (the
        caller already proved identity, and could log in to the target directly,
        so switching grants no new authority). A new refresh family is started.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SwitchTenant",
                service_name="paladin.iam.v1.AuthService",
                input=SwitchTenantRequest,
                output=SwitchTenantResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
